    CreateEngagementInvitationRequest.add_member(:invitation, Smithy::Schema::Shapes::ShapeRef.new(shape: Invitation, location_name: 'Invitation', traits: {"smithy.api#documentation" => "<p> The <code>Invitation</code> object all information necessary to initiate an engagement invitation to a partner. It contains a personalized message from the sender, the invitation's receiver, and a payload. The <code>Payload</code> can be the <code>OpportunityInvitation</code>, which includes detailed structures for sender contacts, partner responsibilities, customer information, and project details. </p>", "smithy.api#required" => {}}))
