    CreateEngagementRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: EngagementDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>Provides a description of the <code>Engagement</code>.</p>", "smithy.api#required" => {}}))
    CreateEngagementRequest.add_member(:contexts, Smithy::Schema::Shapes::ShapeRef.new(shape: EngagementContexts, location_name: 'Contexts', traits: {"smithy.api#documentation" => "<p>The <code>Contexts</code> field is a required array of objects, with a maximum of 5 contexts allowed, specifying detailed information about customer projects associated with the Engagement. Each context object contains a <code>Type</code> field indicating the context type, which must be <code>CustomerProject</code> in this version, and a <code>Payload</code> field containing the <code>CustomerProject</code> details. The <code>CustomerProject</code> object is composed of two main components: <code>Customer</code> and <code>Project</code>. The <code>Customer</code> object includes information such as <code>CompanyName</code>, <code>WebsiteUrl</code>, <code>Industry</code>, and <code>CountryCode</code>, providing essential details about the customer. The <code>Project</code> object contains <code>Title</code>, <code>BusinessProblem</code>, and <code>TargetCompletionDate</code>, offering insights into the specific project associated with the customer. This structure allows comprehensive context to be included within the Engagement, facilitating effective collaboration between parties by providing relevant customer and project information.</p>"}))
