    CreateOpportunityRequest.add_member(:catalog, Smithy::Schema::Shapes::ShapeRef.new(shape: CatalogIdentifier, location_name: 'Catalog', traits: {"smithy.api#documentation" => "<p>Specifies the catalog associated with the request. This field takes a string value from a predefined list: <code>AWS</code> or <code>Sandbox</code>. The catalog determines which environment the opportunity is created in. Use <code>AWS</code> to create opportunities in the Amazon Web Services catalog, and <code>Sandbox</code> for testing in secure, isolated environments.</p>", "smithy.api#required" => {}}))
    CreateOpportunityRequest.add_member(:primary_needs_from_aws, Smithy::Schema::Shapes::ShapeRef.new(shape: PrimaryNeedsFromAws, location_name: 'PrimaryNeedsFromAws', traits: {"smithy.api#documentation" => "<p>Identifies the type of support the partner needs from Amazon Web Services.</p> <p>Valid values:</p> <ul> <li> <p>Cosell—Architectural Validation: Confirmation from Amazon Web Services that the partner's proposed solution architecture is aligned with Amazon Web Services best practices and poses minimal architectural risks.</p> </li> <li> <p>Cosell—Business Presentation: Request Amazon Web Services seller's participation in a joint customer presentation.</p> </li> <li> <p>Cosell—Competitive Information: Access to Amazon Web Services competitive resources and support for the partner's proposed solution.</p> </li> <li> <p>Cosell—Pricing Assistance: Connect with an Amazon Web Services seller for support situations where a partner may be receiving an upfront discount on a service (for example: EDP deals).</p> </li> <li> <p>Cosell—Technical Consultation: Connect with an Amazon Web Services Solutions Architect to address the partner's questions about the proposed solution.</p> </li> <li> <p>Cosell—Total Cost of Ownership Evaluation: Assistance with quoting different cost savings of proposed solutions on Amazon Web Services versus on-premises or a traditional hosting environment.</p> </li> <li> <p>Cosell—Deal Support: Request Amazon Web Services seller's support to progress the opportunity (for example: joint customer call, strategic positioning).</p> </li> <li> <p>Cosell—Support for Public Tender/RFx: Opportunity related to the public sector where the partner needs Amazon Web Services RFx support.</p> </li> </ul>"}))
    CreateOpportunityRequest.add_member(:national_security, Smithy::Schema::Shapes::ShapeRef.new(shape: NationalSecurity, location_name: 'NationalSecurity', traits: {"smithy.api#documentation" => "<p>Indicates whether the <code>Opportunity</code> pertains to a national security project. This field must be set to <code>true</code> only when the customer's industry is <i>Government</i>. Additional privacy and security measures apply during the review and management process for opportunities marked as <code>NationalSecurity</code>.</p>"}))
    CreateOpportunityRequest.add_member(:partner_opportunity_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'PartnerOpportunityIdentifier', traits: {"smithy.api#documentation" => "<p>Specifies the opportunity's unique identifier in the partner's CRM system. This value is essential to track and reconcile because it's included in the outbound payload to the partner.</p> <p>This field allows partners to link an opportunity to their CRM, which helps to ensure seamless integration and accurate synchronization between the Partner Central API and the partner's internal systems.</p>", "smithy.api#length" => {"max" => 64}}))
    CreateOpportunityRequest.add_member(:customer, Smithy::Schema::Shapes::ShapeRef.new(shape: Customer, location_name: 'Customer', traits: {"smithy.api#documentation" => "<p>Specifies customer details associated with the <code>Opportunity</code>.</p>"}))
    CreateOpportunityRequest.add_member(:project, Smithy::Schema::Shapes::ShapeRef.new(shape: Project, location_name: 'Project', traits: {"smithy.api#documentation" => "<p>An object that contains project details for the <code>Opportunity</code>.</p>"}))
    CreateOpportunityRequest.add_member(:opportunity_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OpportunityType, location_name: 'OpportunityType', traits: {"smithy.api#documentation" => "<p>Specifies the opportunity type as a renewal, new, or expansion.</p> <p>Opportunity types:</p> <ul> <li> <p>New opportunity: Represents a new business opportunity with a potential customer that's not previously engaged with your solutions or services.</p> </li> <li> <p>Renewal opportunity: Represents an opportunity to renew an existing contract or subscription with a current customer, ensuring continuity of service.</p> </li> <li> <p>Expansion opportunity: Represents an opportunity to expand the scope of an existing contract or subscription, either by adding new services or increasing the volume of existing services for a current customer.</p> </li> </ul>"}))
    CreateOpportunityRequest.add_member(:marketing, Smithy::Schema::Shapes::ShapeRef.new(shape: Marketing, location_name: 'Marketing', traits: {"smithy.api#documentation" => "<p>This object contains marketing details and is optional for an opportunity.</p>"}))
    CreateOpportunityRequest.add_member(:software_revenue, Smithy::Schema::Shapes::ShapeRef.new(shape: SoftwareRevenue, location_name: 'SoftwareRevenue', traits: {"smithy.api#documentation" => "<p>Specifies details of a customer's procurement terms. This is required only for partners in eligible programs.</p>"}))
    CreateOpportunityRequest.add_member(:client_token, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'ClientToken', traits: {"smithy.api#documentation" => "<p>Required to be unique, and should be unchanging, it can be randomly generated or a meaningful string.</p> <p>Default: None</p> <p>Best practice: To help ensure uniqueness and avoid conflicts, use a Universally Unique Identifier (UUID) as the <code>ClientToken</code>. You can use standard libraries from most programming languages to generate this. If you use the same client token, the API returns the following error: \"Conflicting client token submitted for a new request body.\"</p>", "smithy.api#idempotencyToken" => {}, "smithy.api#length" => {"min" => 1}, "smithy.api#required" => {}}))
    CreateOpportunityRequest.add_member(:life_cycle, Smithy::Schema::Shapes::ShapeRef.new(shape: LifeCycle, location_name: 'LifeCycle', traits: {"smithy.api#documentation" => "<p>An object that contains lifecycle details for the <code>Opportunity</code>.</p>"}))
    CreateOpportunityRequest.add_member(:origin, Smithy::Schema::Shapes::ShapeRef.new(shape: OpportunityOrigin, location_name: 'Origin', traits: {"smithy.api#documentation" => "<p>Specifies the origin of the opportunity, indicating if it was sourced from Amazon Web Services or the partner. For all opportunities created with <code>Catalog: AWS</code>, this field must only be <code>Partner Referral</code>. However, when using <code>Catalog: Sandbox</code>, you can set this field to <code>AWS Referral</code> to simulate Amazon Web Services referral creation. This allows Amazon Web Services-originated flows testing in the sandbox catalog.</p>"}))
    CreateOpportunityRequest.add_member(:opportunity_team, Smithy::Schema::Shapes::ShapeRef.new(shape: PartnerOpportunityTeamMembersList, location_name: 'OpportunityTeam', traits: {"smithy.api#documentation" => "<p>Represents the internal team handling the opportunity. Specify collaborating members of this opportunity who are within the partner's organization.</p>"}))
