    GetOpportunityResponse.add_member(:customer, Smithy::Schema::Shapes::ShapeRef.new(shape: Customer, location_name: 'Customer', traits: {"smithy.api#documentation" => "<p>Specifies details of the customer associated with the <code>Opportunity</code>.</p>"}))
