    Project.add_member(:additional_comments, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'AdditionalComments', traits: {"smithy.api#documentation" => "<p>Captures additional comments or information for the <code>Opportunity</code> that weren't captured in other fields.</p>", "smithy.api#length" => {"min" => 1, "max" => 255}}))
